/**
 * Casual Real-Talk -- Daily speakable phrases from casual YouTube creators
 * 1 video / day -- 10 phrases per video
 * Source: MrBeast, Casey Neistat, Emma Chamberlain, Try Guys, Ryan Trahan, etc.
 *
 * Curation rule (different from /english/podcast):
 *   - Length: 1-7 words. Speakable in <2 seconds.
 *   - Drop-in usable in ANY conversation (not topic-locked).
 *   - Function: reaction / softener / interjection / opener / discourse marker.
 *   - Frequency: heard 100+ times if you watch enough.
 *   - "本当に話せるようになる" filter -- the stuff Japanese speakers freeze on.
 */

import { CASUAL_JULY_SOURCES, CASUAL_JULY_SEEDS } from './casual-july-generated';
import { CASUAL_AUGUST_SOURCES, CASUAL_AUGUST_SEEDS } from './casual-august-generated';
import { CASUAL_SEPTEMBER_SOURCES, CASUAL_SEPTEMBER_SEEDS } from './casual-september-generated';
import { CASUAL_OCTOBER_SOURCES, CASUAL_OCTOBER_SEEDS } from './casual-october-generated';

export interface CasualSource {
    date: string;       // YYYY-MM-DD
    creator: string;    // 'MrBeast', 'Casey Neistat', etc.
    title: string;
    youtubeId: string;
    url: string;
    tagline: string;    // 日本語、なぜこの動画が「話せる英語」として優秀か
}

export type CasualFunction =
    | 'reaction'      // 反応 (no way / oh my gosh / are you telling me)
    | 'softener'      // 和らげ (not gonna lie / to be fair / I don't know if)
    | 'interjection'  // 割り込み (hold up / wait wait / hang on)
    | 'opener'        // 切り出し (first things first / so / alright)
    | 'connector'     // 繋ぎ (you know / I mean / like)
    | 'agreement'     // 同意 (for real / 100% / dead on)
    | 'intensifier'   // 強調 (no joke / literally / dead serious)
    | 'cheer'         // 応援 (let's go / let's do this)
    | 'phrasal'       // 句動詞 (got my hands on / pull this off)
    | 'declaration'   // 宣言・約束 (I'll be there for you / I've got your back / we're family)
    | 'concession';   // 譲歩 (fair enough / you have a point / I'll give you that)

export interface CasualEntry {
    daySlot: number;        // 1-31
    expression: string;     // short, speakable
    source?: string;        // per-entry attribution e.g., "The Office — Michael apologizing"
    contextBefore: string;
    target: string;
    contextAfter: string;
    note: string;           // とにおコメント, focused on WHEN to say it
    rank: 'S' | 'A' | 'B' | 'C';
    func: CasualFunction;
    month?: string;
}

// NOTE: youtubeId field is left blank for entries 2026-05-12 onwards.
// `url` uses YouTube search (always works) so the link never 404s.
// Swap in a specific videoId + watch?v= URL when you want to lock the source.

